// Mobile photography takes priority for both the key and its fallback.
export function resolveContentAsset(key, fallbackKey = '') {
  const primary = contentAssets[key || ''];
  const fallback = contentAssets[fallbackKey || ''];
  if (primary?.kind === 'photograph') return primary;
  if (fallback?.kind === 'photograph') return fallback;
  return primary || fallback;
}
